@@ -0,0 +1,40 @@
+package config
+
+import (
+	"testing"
+	"time"
+
+	"github.com/future-architect/vuls/constant"
+)
+
+func TestUpdatedOSLifecycle(t *testing.T) {
+	tests := []struct {
+		family, release string
+		cutoff          time.Time
+		ended           bool
+	}{
+		{constant.Fedora, "37", time.Date(2023, 12, 5, 23, 59, 59, 0, time.UTC), false},
+		{constant.Fedora, "38", time.Date(2024, 5, 21, 23, 59, 59, 0, time.UTC), false},
+		{constant.Fedora, "40", time.Date(2025, 5, 13, 23, 59, 59, 0, time.UTC), false},
+		{constant.SUSEEnterpriseDesktop, "13", time.Date(2026, 4, 30, 23, 59, 59, 0, time.UTC), false},
+		{constant.SUSEEnterpriseDesktop, "14", time.Date(2028, 11, 30, 23, 59, 59, 0, time.UTC), false},
+		{constant.SUSEEnterpriseServer, "13", time.Date(2026, 4, 30, 23, 59, 59, 0, time.UTC), false},
+		{constant.SUSEEnterpriseServer, "14", time.Date(2028, 11, 30, 23, 59, 59, 0, time.UTC), false},
+		{constant.MacOS, "11", time.Time{}, true},
+		{constant.MacOS, "12", time.Time{}, false},
+		{constant.MacOS, "13", time.Time{}, false},
+		{constant.MacOS, "14", time.Time{}, false},
+		{constant.MacOS, "15", time.Time{}, false},
+	}
+	for _, tt := range tests {
+		t.Run(tt.family+"/"+tt.release, func(t *testing.T) {
+			got, found := GetEOL(tt.family, tt.release)
+			if !found || got.StandardSupportUntil != tt.cutoff || got.Ended != tt.ended {
+				t.Fatalf("GetEOL(%q, %q) = %+v, found %t; want cutoff %s, ended %t", tt.family, tt.release, got, found, tt.cutoff, tt.ended)
+			}
+			if !tt.cutoff.IsZero() && (!got.IsStandardSupportEnded(tt.cutoff.Add(time.Second)) || got.IsStandardSupportEnded(tt.cutoff)) {
+				t.Fatalf("support cutoff %s is not inclusive", tt.cutoff)
+			}
+		})
+	}
+}
