@@ -0,0 +1,80 @@
+package scanner
+
+import (
+	"fmt"
+	"strconv"
+	"testing"
+)
+
+func TestRecentWindowsRollups(t *testing.T) {
+	tests := []struct {
+		family, version, build, release string
+		updates                         []windowsRelease
+	}{
+		{"Client", "10", "19045", "Windows 10 Version 22H2", []windowsRelease{{revision: "3693", kb: "5032189"}, {revision: "4529", kb: "5039211"}}},
+		{"Client", "11", "22621", "Windows 11 Version 22H2", []windowsRelease{{revision: "2715", kb: "5032190"}, {revision: "3737", kb: "5039212"}}},
+		{"Client", "11", "22631", "Windows 11 Version 23H2", []windowsRelease{{revision: "2715", kb: "5032190"}, {revision: "3737", kb: "5039212"}}},
+		{"Server", "2022", "20348", "Windows Server 2022", []windowsRelease{{revision: "2113", kb: "5032198"}, {revision: "2655", kb: "5039227"}}},
+	}
+	for _, tt := range tests {
+		t.Run(tt.build, func(t *testing.T) {
+			rollup := windowsReleases[tt.family][tt.version][tt.build].rollup
+			previous := -1
+			for _, r := range rollup {
+				rev, err := strconv.Atoi(r.revision)
+				if err != nil || rev <= previous {
+					t.Fatalf("revision order invalid at %+v", r)
+				}
+				previous = rev
+			}
+			for _, update := range tt.updates {
+				found := false
+				for _, r := range rollup {
+					found = found || r == update
+				}
+				if !found {
+					t.Errorf("missing %+v", update)
+				}
+			}
+			for _, rev := range []string{"2000", "9999"} {
+				got, err := DetectKBsFromKernelVersion(tt.release, fmt.Sprintf("10.0.%s.%s", tt.build, rev))
+				if err != nil {
+					t.Fatal(err)
+				}
+				for _, update := range tt.updates {
+					kbs := got.Unapplied
+					if rev == "9999" {
+						kbs = got.Applied
+					}
+					found := false
+					for _, kb := range kbs {
+						found = found || kb == update.kb
+					}
+					if !found {
+						t.Errorf("revision %s: KB %s not classified as expected", rev, update.kb)
+					}
+				}
+			}
+		})
+	}
+}
+
+func TestWindows11SharedRollups(t *testing.T) {
+	rollup22H2 := windowsReleases["Client"]["11"]["22621"].rollup
+	rollup23H2 := windowsReleases["Client"]["11"]["22631"].rollup
+	shared := make(map[string]string)
+	for _, r := range rollup22H2 {
+		if revision, err := strconv.Atoi(r.revision); err == nil && revision >= 2506 {
+			shared[r.revision] = r.kb
+		}
+	}
+	for _, r := range rollup23H2[1:] {
+		if kb, ok := shared[r.revision]; !ok || kb != r.kb {
+			t.Errorf("22631 revision %s KB %s differs from 22621", r.revision, r.kb)
+		}
+		delete(shared, r.revision)
+	}
+	if len(shared) != 0 {
+		t.Errorf("22631 is missing shared revisions: %v", shared)
+	}
+}
